using BenchmarkDotNet.Attributes;
using BenchmarkDotNet.Configs;
using BenchmarkDotNet.Environments;
using BenchmarkDotNet.Jobs;
using BenchmarkDotNet.Running;
using TextAnalysis;

var config = DefaultConfig.Instance
    .AddJob(Job.Default.WithRuntime(CoreRuntime.Core90).AsBaseline())
    .AddJob(Job.Default.WithRuntime(CoreRuntime.Core100));

BenchmarkRunner.Run<TextAnalyzerBenchmarks>(config, args);

[MemoryDiagnoser]
public class TextAnalyzerBenchmarks
{
    private TextAnalyzer _analyzer = null!;

    [GlobalSetup]
    public void Setup()
    {
        // Build a realistic text corpus (~500 words)
        var words = new[]
        {
            "the", "quick", "brown", "fox", "jumps", "over", "lazy", "dog",
            "performance", "benchmarking", "is", "essential", "for", "understanding",
            "how", "code", "behaves", "under", "different", "runtime", "versions",
            "dotnet", "framework", "provides", "powerful", "tools", "to", "measure",
            "execution", "time", "and", "memory", "allocation", "patterns",
            "a", "histogram", "shows", "distribution", "of", "word", "lengths",
            "unique", "counting", "uses", "hash", "set", "internally",
            "average", "calculation", "iterates", "through", "all", "elements"
        };
        var rng = new Random(42);
        var parts = new string[500];
        for (int i = 0; i < parts.Length; i++)
            parts[i] = words[rng.Next(words.Length)];

        _analyzer = new TextAnalyzer(string.Join(' ', parts));
    }

    [Benchmark]
    public double AverageWordLength() => _analyzer.AverageWordLength();

    [Benchmark]
    public object WordLengthHistogram() => _analyzer.WordLengthHistogram();

    [Benchmark]
    public int UniqueWordCount() => _analyzer.UniqueWordCount();
}

