using System.Diagnostics;
using TextAnalysis;

// Build a realistic text corpus (~500 words)
var seedWords = new[]
{
    "the", "quick", "brown", "fox", "jumps", "over", "lazy", "dog",
    "performance", "benchmarking", "is", "essential", "for", "understanding",
    "how", "code", "behaves", "under", "different", "runtime", "versions",
    "dotnet", "framework", "provides", "powerful", "tools", "to", "measure",
    "execution", "time", "and", "memory", "allocation", "patterns",
    "a", "histogram", "shows", "distribution", "of", "word", "lengths",
    "unique", "counting", "uses", "hash", "set", "internally",
    "average", "calculation", "iterates", "through", "all", "elements"
};
var rng = new Random(42);
var parts = new string[500];
for (int i = 0; i < parts.Length; i++)
    parts[i] = seedWords[rng.Next(seedWords.Length)];
var text = string.Join(' ', parts);

var analyzer = new TextAnalyzer(text);

// Warmup
for (int i = 0; i < 1000; i++)
{
    analyzer.AverageWordLength();
    analyzer.WordLengthHistogram();
    analyzer.UniqueWordCount();
}

const int iterations = 100_000;
var sw = new Stopwatch();

// AverageWordLength
var avgTimes = new double[5];
for (int run = 0; run < 5; run++)
{
    sw.Restart();
    for (int i = 0; i < iterations; i++)
        analyzer.AverageWordLength();
    sw.Stop();
    avgTimes[run] = sw.Elapsed.TotalNanoseconds / iterations;
}

// WordLengthHistogram
var histTimes = new double[5];
for (int run = 0; run < 5; run++)
{
    sw.Restart();
    for (int i = 0; i < iterations; i++)
        analyzer.WordLengthHistogram();
    sw.Stop();
    histTimes[run] = sw.Elapsed.TotalNanoseconds / iterations;
}

// UniqueWordCount
var uniqTimes = new double[5];
for (int run = 0; run < 5; run++)
{
    sw.Restart();
    for (int i = 0; i < iterations; i++)
        analyzer.UniqueWordCount();
    sw.Stop();
    uniqTimes[run] = sw.Elapsed.TotalNanoseconds / iterations;
}

string runtime = System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription;
Console.WriteLine($"Runtime: {runtime}");
Console.WriteLine($"Iterations per measurement: {iterations:N0}");
Console.WriteLine();
Console.WriteLine($"{"Method",-25} {"Mean (ns)",12} {"StdDev (ns)",12}");
Console.WriteLine(new string('-', 51));
PrintResult("AverageWordLength", avgTimes);
PrintResult("WordLengthHistogram", histTimes);
PrintResult("UniqueWordCount", uniqTimes);

static void PrintResult(string name, double[] times)
{
    double mean = times.Average();
    double stddev = Math.Sqrt(times.Select(t => (t - mean) * (t - mean)).Average());
    Console.WriteLine($"{name,-25} {mean,12:F2} {stddev,12:F2}");
}

